SS('z-next', 'איפה אנחנו במשפך, ולאן ממשיכים',
   FLOW([('🗺️', 'תהליך עסקי', 'מפגש 1'), ('🎯', 'החלטה', 'מפגש 1'), ('📝', 'דרישות', 'מפגש 1'), ('🧱', 'נתונים', 'היום'),
         ('🔎', 'שאילתות', 'מפגשים 3 ו-4'), ('🖥️', 'מערכת', 'בהמשך'), ('📊', 'לוח מחוונים', 'בהמשך'), ('📣', 'בקרה ותקשורת', 'בהמשך')], 1, 'w8') +
   BAND('dg', '**במפגש 3:** שואלים את שש הטבלאות של היום. כמה פסטות נמכרו, מה שיעור הטעויות בכל משמרת, ואיזה מלצר צריך הדרכה. כל שאילתה נקראת קליק אחר קליק, על אותו מסד.', 9) +
   BAND('do', '**עד המפגש הבא:** חזרו על התרשים של הביסטרו ועל שש שאלות הבדיקה, ופתרו את התרגילים המסכמים על העמותה.', 10) +
   BAND('real', 'את המודל שבנינו כאן ברמת ההיגיון, ד״ר עופרה אור תיקח לרמת פריסת הפרויקט בשטח.', 11))

